export async function handleIdempotentRequest(
  key: string,
  reqHandler: () => Promise<{ status: number; body: any }>
) {
  const redisKey = `idempotency:${key}`;

  // 1. Attempt atomic lock acquisition (NX = only set if not exists)
  const acquired = await redis.set(redisKey, JSON.stringify({ state: 'PROCESSING' }), 'NX', 'EX', 120);

  if (!acquired) {
    const existing = JSON.parse((await redis.get(redisKey))!);
    if (existing.state === 'PROCESSING') {
      // Concurrent request in-flight; reject duplicate execution
      return { status: 409, body: { error: 'Request currently processing' } };
    }
    // Previously completed; return identical cached response directly
    return { status: existing.status, body: existing.body };
  }

  try {
    // 2. Execute business logic
    const response = await reqHandler();
    // 3. Cache completed outcome for 24 hours
    await redis.set(redisKey, JSON.stringify({ state: 'COMPLETED', ...response }), 'EX', 86400);
    return response;
  } catch (err) {
    // Remove lock on unexpected failure so client can retry
    await redis.del(redisKey);
    throw err;
  }
}
